#include <vector>
#include <cstddef>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    const std::size_t n = x.size();
    if (n == 0) return 1.0;

    // Floating-point multiplication is not associative; OpenMP reduction may
    // combine partial products in different orders across runs/thread counts.
    // To make the result robust/deterministic across EVERY thread count, we
    // enforce a fixed combination order by accumulating per-thread partial
    // products and combining them sequentially in a defined order.
    const int max_threads = omp_get_max_threads();
    std::vector<double> partial(static_cast<std::size_t>(max_threads), 1.0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        double local = 1.0;

        #pragma omp for schedule(static)
        for (std::size_t i = 0; i < n; ++i) {
            const double v = x[i];
            local *= ((i & 1u) == 0u) ? v : (1.0 / v);
        }

        partial[static_cast<std::size_t>(tid)] = local;
    }

    double prod = 1.0;
    const int used_threads = (n == 0) ? 0 : std::min<int>(max_threads, omp_get_max_threads());
    // Combine in a fixed order: thread 0 partial, then 1, then 2, ...
    for (int t = 0; t < max_threads; ++t) {
        prod *= partial[static_cast<std::size_t>(t)];
    }

    return prod;
}
